## Why This Is Asked
Tests automation of security incident response in a complex SAP on AWS environment, focusing on real-world tooling and cross-account controls.

## Key Concepts
- RFC anomaly detection via CloudWatch and GuardDuty
- Cross-account IAM roles with MFA-protected STS elevation
- Automated network isolation through security group modifications
- Secrets rotation for SAP credentials in AWS Secrets Manager
- Step Functions orchestration for workflow and audit trails

## Code Example
```javascript
{
  "Comment": "SAP incident response state machine",
  "StartAt": "DetectAnomaly",
  "States": {
    "DetectAnomaly": {
      "Type": "Choice",
      "Choices": [
        {
          "Variable": "$.alert_type",
          "StringEquals": "RFC_ANOMALY",
          "Next": "AssumeRemediationRole"
        }
      ],
      "Default": "LogAndDismiss"
    },
    "AssumeRemediationRole": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:assume-role-with-mfa",
      "Next": "IsolateHost"
    },
    "IsolateHost": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:isolate-sap-host",
      "Next": "RotateCredentials"
    },
    "RotateCredentials": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:rotate-sap-secrets",
      "Next": "NotifyAndLog"
    },
    "NotifyAndLog": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:notify-and-log",
      "End": true
    },
    "LogAndDismiss": {
      "Type": "Pass",
      "End": true
    }
  }
}
```

## Minimal IaC Sketch (Terraform)
```hcl
resource "aws_sfn_state_machine" "sap_incident_response" {
  name     = "sap-incident-response"
  role_arn = aws_iam_role.stepfunctions_role.arn
  definition = file("${path.module}/state_machine.json")
}

resource "aws_iam_role" "cross_account_remediation" {
  name = "sap-remediation-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { AWS = "arn:aws:iam::123456789:role/sap-incident-response-role" },
      Action = "sts:AssumeRole",
      Condition = { Bool = { "aws:MultiFactorAuthPresent" = true } }
    }]
  })
}

resource "aws_security_group_rule" "sap_isolation" {
  count = 1
  type        = "ingress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  description = "Emergency isolation"
  source_security_group_id = aws_security_group.sap_management.id
}
```

